#!/bin/sh
# Package a release build as wherebox-<version>-<target>.tar.gz (.zip on
# Windows): the binary, LICENSE, README.md, man pages and shell completions
# generated by the binary itself. Used by scripts/publish.sh.
#
#   scripts/package.sh <version> <target> [outdir]
#
# Expects target/<target>/release/wherebox[.exe]; the build must run on the
# host (completions and man pages come from executing it).
set -eu

version=$1
target=$2
outdir=${3:-dist}

case $target in
*windows*) exe=wherebox.exe ;;
*) exe=wherebox ;;
esac
bin="target/$target/release/$exe"
[ -x "$bin" ] || { echo "package.sh: $bin not found" >&2; exit 1; }

name="wherebox-$version-$target"
stage=$(mktemp -d)
trap 'rm -rf "$stage"' EXIT
dir="$stage/$name"
mkdir -p "$dir/completions" "$dir/man" "$outdir"

cp "$bin" LICENSE README.md "$dir/"
"$bin" man --dir "$dir/man" 2>/dev/null
"$bin" completions bash >"$dir/completions/wherebox.bash"
"$bin" completions zsh >"$dir/completions/_wherebox"
"$bin" completions fish >"$dir/completions/wherebox.fish"
"$bin" completions elvish >"$dir/completions/wherebox.elv"
"$bin" completions powershell >"$dir/completions/_wherebox.ps1"
"$bin" completions nushell >"$dir/completions/wherebox.nu"

outdir=$(cd "$outdir" && pwd)
case $target in
*windows*)
    archive="$outdir/$name.zip"
    (cd "$stage" && 7z a -tzip "$name.zip" "$name" >/dev/null)
    mv "$stage/$name.zip" "$archive"
    ;;
*)
    archive="$outdir/$name.tar.gz"
    tar -C "$stage" -czf "$archive" "$name"
    ;;
esac
echo "$archive"
